import { invoke } from '@tauri-apps/api/core';

export const captureClient = {
  async startCapture(options: CaptureOptions): Promise<CaptureSession> {
    return invoke('start_capture', { options });
  },

  async stopCapture(sessionId: string): Promise<void> {
    return invoke('stop_capture', { sessionId });
  },

  subscribeToFrames(sessionId: string, onFrame: (frame: Frame) => void): () => void {
    // WebSocket subscription logic
  }
};
```

